// Full integration test for the out-of-framework custom scale layer.
//
// Boundary: this file includes only the public API header and links only the
// built framework libraries + the custom plugin. No framework test fixtures or
// internal layer headers are used. Reference data is generated by the
// CustomScaleLayer_Test_1 cell of
// test/python_validation/numpy_unit_tests.ipynb.
#include <api/tensor.h>

#include <cmath>
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>

// Forces the custom layer plugin to be linked and loaded.
extern "C" void ld_custom_layers_load();

namespace {

int failures = 0;

void check(bool condition, const std::string &message) {
  if (!condition) {
    std::cerr << "FAILED: " << message << '\n';
    ++failures;
  }
}

void check_near(double actual, double expected, double tolerance,
                const std::string &where) {
  if (!std::isfinite(actual) || std::abs(actual - expected) > tolerance) {
    std::cerr << "FAILED: " << where << " actual=" << actual
              << " expected=" << expected << '\n';
    ++failures;
  }
}

std::vector<std::float64_t> load_bin(const std::string &name,
                                     std::size_t expected_size) {
  const std::string path =
      std::string(LD_CUSTOM_TEST_DATA_DIR) + "/" + name;
  std::ifstream file(path, std::ios::binary);
  if (!file)
    throw std::runtime_error("Failed to open " + path);

  std::vector<std::float64_t> data(expected_size);
  file.read(reinterpret_cast<char *>(data.data()),
            static_cast<std::streamsize>(expected_size * sizeof(std::float64_t)));
  if (!file)
    throw std::runtime_error("Failed to read " + path);
  return data;
}

} // namespace

int main() {
  ld_custom_layers_load();

  constexpr unsigned input_features = 17;
  constexpr unsigned batch_size = 128;
  constexpr unsigned epochs = 1;
  constexpr unsigned samples = input_features * batch_size;

  auto input_data = load_bin("CustomScale_Test_1_input_data.bin", samples);
  auto target_data = load_bin("CustomScale_Test_1_target_data.bin", samples);
  const auto expected_scale =
      load_bin("CustomScale_Test_1_scale_data.bin", 1).front();
  const auto expected_output =
      load_bin("CustomScale_Test_1_output_data.bin", samples);
  const auto expected_loss = load_bin("CustomScale_Test_1_loss_data.bin", 1);
  const auto expected_grad_loss =
      load_bin("CustomScale_Test_1_grad_loss_data.bin", samples);
  const auto expected_grad_input =
      load_bin("CustomScale_Test_1_grad_input_data.bin", samples);

  // Framework-style tensors: feature-fastest storage, [features, batch].
  tf::tensor x, input, target_output;
  x.tf_create(tf_float64, input_features, batch_size);
  input.tf_create(tf_float64, input_features, batch_size);
  target_output.tf_create(tf_float64, input_features, batch_size);
  input.tensor_of(input_data.data());
  target_output.tensor_of(target_data.data());

  tf::layer::layer custom_layer("test_scale");
  check(custom_layer.valid(), "custom scale layer was registered");
  custom_layer.setParameter("scale", expected_scale);

  const auto scale_values = custom_layer.getParameter("scale");
  check(scale_values.size() == 1, "custom layer reports its scale parameter");
  if (scale_values.size() == 1 && scale_values.front().getPtr())
    check_near(scale_values.front().getData()[0], expected_scale, 1e-12,
               "configured scale");

  auto custom_output = custom_layer({x});
  check(custom_output.size() == 1, "custom layer returns one output tensor");

  tf::callback::trace call_back;
  call_back.record_parameter_on_batch_end(custom_layer, "training_output",
                                          false);
  call_back.record_parameter_on_batch_end(custom_layer, "grad_input", false);

  tf::model model({x}, custom_output);
  model.shuffle(false);
  model.compile(OptimizerType::SGD, tf::loss::type::squared_error);

  auto loss = model.get_model_loss(custom_output[0]);
  call_back.record_tensor_loss_on_batch_end(
      loss, tf::loss::parameter::squared_error_predicted_output);
  call_back.record_tensor_loss_on_batch_end(
      loss, tf::loss::parameter::squared_error_grad_predicted_output);
  call_back.record_scalar_loss_on_batch_end(loss);

  model.fit({input}, {target_output}, {call_back.callback()}, epochs,
            batch_size);

  const auto outputs =
      call_back.get_parameter_on_batch_end(custom_layer, "training_output");
  const auto grad_inputs =
      call_back.get_parameter_on_batch_end(custom_layer, "grad_input");
  const auto predicted = call_back.get_tensor_loss_on_batch_end(
      loss, tf::loss::parameter::squared_error_predicted_output);
  const auto grad_predicted = call_back.get_tensor_loss_on_batch_end(
      loss, tf::loss::parameter::squared_error_grad_predicted_output);
  const auto losses = call_back.get_scaler_loss_on_batch_end(loss);

  check(outputs.size() == epochs, "one batch of training outputs recorded");
  check(grad_inputs.size() == epochs, "one batch of input gradients recorded");
  check(losses.size() == epochs, "one batch of scalar losses recorded");

  if (outputs.size() == epochs && !outputs.front().empty() &&
      !outputs.front().front().empty()) {
    const std::float64_t *values = outputs.front().front().front().getData();
    for (unsigned j = 0; j < batch_size; ++j)
      for (unsigned i = 0; i < input_features; ++i)
        check_near(values[i + j * input_features],
                   expected_output[i + j * input_features], 1e-9,
                   "training_output");
  } else {
    check(false, "training_output tensor is available");
  }

  if (grad_inputs.size() == epochs && !grad_inputs.front().empty() &&
      !grad_inputs.front().front().empty()) {
    const std::float64_t *values = grad_inputs.front().front().front().getData();
    for (unsigned k = 0; k < samples; ++k)
      check_near(values[k], expected_grad_input[k], 1e-9, "grad_input");
  } else {
    check(false, "grad_input tensor is available");
  }

  // tf::loss::parameter::squared_error_predicted_output exposes the loss's
  // scalar batch-loss tensor (same convention as DenseLayer_Test_1).
  if (predicted.size() == epochs && !predicted.front().empty() &&
      !predicted.front().front().empty()) {
    check_near(predicted.front().front().front().getData()[0],
               expected_loss.front(), 1e-9, "loss tensor");
  } else {
    check(false, "loss tensor is available");
  }

  if (grad_predicted.size() == epochs && !grad_predicted.front().empty() &&
      !grad_predicted.front().front().empty()) {
    const std::float64_t *values =
        grad_predicted.front().front().front().getData();
    for (unsigned k = 0; k < samples; ++k)
      check_near(values[k], expected_grad_loss[k], 1e-9, "loss gradient");
  } else {
    check(false, "loss gradient tensor is available");
  }

  if (!losses.empty() && !losses.front().empty())
    check_near(losses.front().front(), expected_loss.front(), 1e-9, "loss");
  else
    check(false, "scalar loss is available");

  if (failures != 0) {
    std::cerr << failures << " custom integration check(s) failed\n";
    return 1;
  }

  std::cout << "custom scale layer integration checks passed\n";
  return 0;
}
